mapper.insert:
update user_asset_token
set num         = #{num},
    update_time = #{time}
where goods_id = #{goodsId}
  and sku_id = #{skuId}
  and address = #{address}
  and ct_id = #{ctId}
  and token_id = #{tokenId}

mapper.select:
select *
from user_asset_token
where address = #{address}
  and ct_id = #{ctId}
  and token_id = #{tokenId}

select *
from user_asset_token
where goods_id = #{goodsId}
  and address = #{address}
  and num > 0
order by update_time desc

select uat.*
from user_asset_token uat
left join goods_spu spu on uat.goods_id = spu.goods_id
left join goods_sku sku on uat.sku_id = sku.sku_id

    uat.num > 0

        and uat.address = #{address}




                and (spu.type = 0 or (spu.type = 1 and sku.blind_box_type = 0))


                and spu.type = 1 and sku.blind_box_type = 1




        and (
        uat.address = #{vague}
        or uat.token_id = #{vague}
        or uat.sku_id = #{vague}
        or uat.goods_id = #{vague}
        or spu.name like CONCAT('%', #{vague}, '%')
        or sku.name like CONCAT('%', #{vague}, '%')
        or sku.token_name like CONCAT('%', #{vague}, '%')
        )


order by uat.update_time desc
